"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[35168],{3331:(a,n,e)=>{e.d(n,{R:()=>s,x:()=>u});var i=e(36672);const t={},r=i.createContext(t);function s(a){const n=i.useContext(r);return i.useMemo((function(){return"function"==typeof a?a(n):{...n,...a}}),[n,a])}function u(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(t):a.components||t:s(a.components),i.createElement(r.Provider,{value:n},a.children)}},21201:(a,n,e)=>{e.r(n),e.d(n,{assets:()=>d,contentTitle:()=>u,default:()=>g,frontMatter:()=>s,metadata:()=>i,toc:()=>m});const i=JSON.parse('{"id":"2023/04/16","title":"2023-04-16","description":"Valve Batasi Akun 2500 Pengguna yang Menandai Review Game Negatif Tidak Bermanfaat","source":"@site/i18n/id/docusaurus-plugin-content-docs/current/2023/04/16.md","sourceDirName":"2023/04","slug":"/2023/04/16","permalink":"/id/2023/04/16","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/id/docusaurus-plugin-content-docs//current/2023/04/16.md","tags":[],"version":"current","frontMatter":{"localized_date":"16 April 2023","top_news":"Valve Batasi Akun 2500 Pengguna yang Menandai Review Game Negatif Tidak Bermanfaat"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-17","permalink":"/id/2023/04/17"},"next":{"title":"2023-04-15","permalink":"/id/2023/04/15"}}');var t=e(23420),r=e(3331);const s={localized_date:"16 April 2023",top_news:"Valve Batasi Akun 2500 Pengguna yang Menandai Review Game Negatif Tidak Bermanfaat"},u="2023-04-16",d={},m=[{value:"Valve Batasi Akun 2500 Pengguna yang Menandai Review Game Negatif Tidak Bermanfaat",id:"valve-batasi-akun-2500-pengguna-yang-menandai-review-game-negatif-tidak-bermanfaat",level:2},{value:"Mengapa harga sandwich kalkun yang dibungkus plastik seharga $15 di bandara NYC?",id:"mengapa-harga-sandwich-kalkun-yang-dibungkus-plastik-seharga-15-di-bandara-nyc",level:2},{value:"Kontrol lalu lintas udara Lofi - LAX",id:"kontrol-lalu-lintas-udara-lofi---lax",level:2},{value:"Apa itu model transformator dan bagaimana cara kerjanya?",id:"apa-itu-model-transformator-dan-bagaimana-cara-kerjanya",level:2},{value:"Dasar-dasar WebGPU",id:"dasar-dasar-webgpu",level:2},{value:"CEO Google: &quot;bisakah kita mengubah pengaturan grup ini menjadi tidak aktif&quot; [pdf]",id:"ceo-google-bisakah-kita-mengubah-pengaturan-grup-ini-menjadi-tidak-aktif-pdf",level:2},{value:"Bertahan dari Kejenuhan (2015)",id:"bertahan-dari-kejenuhan-2015",level:2},{value:"Pengembangan Perangkat Lunak dengan Kode Rendah Adalah Bohong",id:"pengembangan-perangkat-lunak-dengan-kode-rendah-adalah-bohong",level:2},{value:"Kerentanan eksekusi kode jarak jauh di Google yang tidak mau mereka perbaiki",id:"kerentanan-eksekusi-kode-jarak-jauh-di-google-yang-tidak-mau-mereka-perbaiki",level:2},{value:"Pengembangan Hypervisor dalam Karat",id:"pengembangan-hypervisor-dalam-karat",level:2}];function k(a){const n={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...a.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"2023-04-16",children:"2023-04-16"})}),"\n",(0,t.jsx)(n.h2,{id:"valve-batasi-akun-2500-pengguna-yang-menandai-review-game-negatif-tidak-bermanfaat",children:"Valve Batasi Akun 2500 Pengguna yang Menandai Review Game Negatif Tidak Bermanfaat"}),"\n",(0,t.jsxs)(n.p,{children:["(Asli)(",(0,t.jsx)(n.a,{href:"https://tech.slashdot.org/story/23/04/14/175246/valve-restricts-accounts-of-2500-users-who-marked-a-negative-game-review-useful",children:"https://tech.slashdot.org/story/23/04/14/175246/valve-restricts-accounts-of-2500-users-who-marked-a-negative-game-review-useful"}),').\nValve telah membatasi akun 2500 pengguna yang menandai ulasan negatif untuk Warlander berguna, yang mengarah ke larangan 30 hari untuk melakukan voting naik dan turun bagi mereka yang terpengaruh. Moderator Steam mengklasifikasikan ulasan tersebut sebagai "mencoba menipu pengguna atau pelanggaran lain terhadap Peraturan & Panduan Steam," yang mengakibatkan penghapusan ulasan tersebut, dan banyak yang percaya bahwa sistem ulasan tersebut "sama sekali tidak berguna" karena dampak dari tindakan Valve.']}),"\n",(0,t.jsxs)(n.p,{children:["(Discussion Service) (",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35577895",children:"http://news.ycombinator.com/item?id=35577895"}),').\nValve membatasi akun pengguna yang menandai ulasan game negatif yang berguna, sehingga menimbulkan kritik dari pengguna Hacker News tentang izin Valve terhadap "perangkat lunak berbahaya" di platform mereka. Beberapa menyarankan alternatif perangkat lunak anti-cheat, sementara yang lain berpendapat bahwa hal tersebut diperlukan untuk mencegah kecurangan dalam game online. Komentar-komentar tersebut membahas etika monopoli Steam atas distribusi video game PC, dengan berbagai pendapat tentang perlunya monopoli dan keefektifan perangkat lunak anti-cheat.']}),"\n",(0,t.jsx)(n.h2,{id:"mengapa-harga-sandwich-kalkun-yang-dibungkus-plastik-seharga-15-di-bandara-nyc",children:"Mengapa harga sandwich kalkun yang dibungkus plastik seharga $15 di bandara NYC?"}),"\n",(0,t.jsxs)(n.p,{children:["(Asli) (",(0,t.jsx)(n.a,{href:"https://hellgatenyc.com/why-is-airport-turkey-sandwich-expensive",children:"https://hellgatenyc.com/why-is-airport-turkey-sandwich-expensive"}),").\nN/A."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35580847",children:"Discussion Service"}),".\nPengguna Discussion Service memperdebatkan alasan mengapa sandwich kalkun yang dibungkus plastik seharga $15 di bandara NYC; persaingan yang terbatas di dalam bandara dan kurangnya pembanding untuk penjual makanan dan minuman membuat tidak mungkin untuk memastikan harga yang adil. Para pengguna menyarankan agar penumpang membawa makanan sendiri."]}),"\n",(0,t.jsx)(n.h2,{id:"kontrol-lalu-lintas-udara-lofi---lax",children:"Kontrol lalu lintas udara Lofi - LAX"}),"\n",(0,t.jsxs)(n.p,{children:["(Asli) (",(0,t.jsx)(n.a,{href:"https://www.lofiatc.com/?icao=KLAX",children:"https://www.lofiatc.com/?icao=KLAX"}),").\nUnggahan tersebut menggunakan frekuensi Los Angeles Tower (Utara) di KLAX, yaitu 133.900. Postingan ini menyertakan video musik dari Glimlip x Yasper dan menyediakan opsi untuk umpan balik atau donasi."]}),"\n",(0,t.jsxs)(n.p,{children:["(Discussion Service) (",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35583228",children:"http://news.ycombinator.com/item?id=35583228"}),").\nPara pengguna Hacker News mendiskusikan lofiatc.com, sebuah aplikasi web baru yang menggabungkan musik ambien dengan komunikasi kontrol lalu lintas udara dengan cara yang menenangkan, sehingga menarik minat; beberapa pengguna meminta fitur tambahan dan obrolan radio. Para pengguna juga berbagi preferensi mereka untuk musik ambient saat bekerja, dengan rekomendasi untuk SomaFM dan mynoise.net, dan beberapa menyarankan black metal sebagai alternatif yang sesuai, meskipun tidak ada konsensus yang jelas tentang jenis musik ambient yang terbaik untuk konsentrasi."]}),"\n",(0,t.jsx)(n.h2,{id:"apa-itu-model-transformator-dan-bagaimana-cara-kerjanya",children:"Apa itu model transformator dan bagaimana cara kerjanya?"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://txt.cohere.ai/what-are-transformer-models/",children:"Asli"}),".\nModel transformator adalah perkembangan baru dalam pembelajaran mesin dan mahir dalam menghasilkan teks yang koheren dengan melacak konteks. Dengan kemampuan untuk melakukan berbagai tugas, seperti menerjemahkan antar bahasa dan menjawab pertanyaan, transformer terdiri dari berbagai komponen, termasuk tokenisasi, penyematan, pengkodean posisi, blok transformer, dan softmax. Blok transformator yang paling kompleks menggunakan komponen attention dan feedforward, dengan multi-head attention yang digunakan untuk memodifikasi vektor dan memberikan lebih banyak konteks. Pasca-pelatihan mengajarkan transformer untuk melakukan tugas-tugas tertentu, dan kemampuan mereka untuk menangkap konteks telah menghasilkan kesuksesan."]}),"\n",(0,t.jsxs)(n.p,{children:["(Discussion Service) (",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35576918",children:"http://news.ycombinator.com/item?id=35576918"}),").\nPengguna terlibat dalam diskusi tentang model transformer, mempertanyakan keampuhannya dan kelengkapan konten promosi. Metode alternatif untuk tokenisasi disebutkan, dan sumber daya untuk mempelajari lebih lanjut direkomendasikan, termasuk kursus, video, dan makalah. Perilaku yang muncul yang ditunjukkan oleh model sederhana dalam kecerdasan buatan dan hubungan antara detail komputasi dan perilaku tingkat tinggi dieksplorasi, menyoroti area studi aktif yang disebut interpretabilitas mekanistik."]}),"\n",(0,t.jsx)(n.h2,{id:"dasar-dasar-webgpu",children:"Dasar-dasar WebGPU"}),"\n",(0,t.jsxs)(n.p,{children:["(Asli) (",(0,t.jsx)(n.a,{href:"https://webgpufundamentals.org/",children:"https://webgpufundamentals.org/"}),").\nPostingan ini menyediakan sekumpulan artikel untuk mempelajari dasar-dasar WebGPU, termasuk tata letak memori data, matematika 3D, dan WebGPU dari WebGL. Artikel ini juga menyertakan sumber daya dan referensi untuk belajar lebih lanjut, serta kesempatan untuk berkontribusi. Terima kasih kepada jrprice atas kontribusinya."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35579334",children:"Discussion Service"}),".\nWebGPU Fundamentals mendapatkan perhatian di Hacker News sebagai penerus WebGL untuk grafis pada browser web. Para pengguna mendiskusikan aplikasi potensial untuk simulasi, deep learning, dan kekhawatiran tentang fitur-fitur browser. Komentar juga menyinggung tentang sequencer MIDI berbasis web, instrumen eksperimental, dan WebUSB untuk pembaruan firmware. Beberapa orang berpendapat tentang keunggulan alat berbasis web, sementara yang lain mengungkapkan kekhawatiran atas risiko keamanan dan masalah kompatibilitas. WebGPU tidak dimaksudkan untuk tingkat tinggi atau dapat diakses oleh pemula, tetapi API GPU tingkat rendah untuk pengguna ahli."]}),"\n",(0,t.jsx)(n.h2,{id:"ceo-google-bisakah-kita-mengubah-pengaturan-grup-ini-menjadi-tidak-aktif-pdf",children:'CEO Google: "bisakah kita mengubah pengaturan grup ini menjadi tidak aktif" [pdf]'}),"\n",(0,t.jsxs)(n.p,{children:["(Asli) (",(0,t.jsx)(n.a,{href:"https://ia601707.us.archive.org/28/items/gov.uscourts.cand.364454/gov.uscourts.cand.364454.385.0.pdf",children:"https://ia601707.us.archive.org/28/items/gov.uscourts.cand.364454/gov.uscourts.cand.364454.385.0.pdf"}),").\nHacker News mendiskusikan WebGPU Fundamentals, penerus WebGL, karena potensinya dalam pembelajaran mendalam di sisi klien dan simulasi browser. Percakapan juga membahas tentang fitur-fitur browser, potensi kegunaan dan kenyamanannya, dan cakupan browser sebagai aplikasi atau penampil. Selain itu, para pengguna mendiskusikan cara-cara untuk merender teks menggunakan WebGPU, kompatibilitasnya dengan proyek-proyek AI, dan kolaborasi yang sedang berlangsung di antara tim-tim WebGPU."]}),"\n",(0,t.jsxs)(n.p,{children:["(Discussion Service)(",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35585174",children:"http://news.ycombinator.com/item?id=35585174"}),').\nCEO Google Sundar Pichai menghadapi tuduhan meminta perubahan pengaturan grup Google Chat menjadi "history-off", meskipun ada potensi implikasi hukum dan pelanggaran FRCP 37(e). Para pengguna Discussion Service mendiskusikan pentingnya menjaga catatan yang dapat ditemukan dan kekhawatiran atas legalitas praktik penghapusan otomatis, dengan contoh-contoh komunikasi elektronik lain yang menghapus pesan. Selain itu, diskusi mengenai penyimpanan data, peraturan pemerintah, dan monopoli di seluruh dunia juga dibahas, sementara kekhawatiran mengenai bisnis Android Google dan kurangnya persaingan muncul.']}),"\n",(0,t.jsx)(n.h2,{id:"bertahan-dari-kejenuhan-2015",children:"Bertahan dari Kejenuhan (2015)"}),"\n",(0,t.jsxs)(n.p,{children:["(Asli) (",(0,t.jsx)(n.a,{href:"https://lifeofaudrey.com/essays/surviving_burnout.html",children:"https://lifeofaudrey.com/essays/surviving_burnout.html"}),").\nKelelahan dalam industri teknologi disebabkan oleh ketidakselarasan tanggung jawab, otoritas, dan sumber daya. Pengalaman penulis dengan burnout mendorongnya untuk berhenti dari pekerjaannya dan memasuki masa pemulihan, yang kemudian membawanya untuk memulai bisnisnya sendiri. Burnout adalah masalah struktural yang membutuhkan solusi struktural, dengan dukungan pemulihan dan dana yang diperlukan bagi mereka yang terkena dampaknya."]}),"\n",(0,t.jsxs)(n.p,{children:["(Discussion Service) (",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35577285",children:"http://news.ycombinator.com/item?id=35577285"}),").\nSebuah artikel di Hacker News membahas pentingnya menemukan keseimbangan untuk menghindari kelelahan dan menjaga kesehatan mental dan fisik, sementara para pengguna berbagi pengalaman pribadi dan menawarkan saran. Beberapa pengguna Discussion Service menyoroti perbedaan antara depresi dan kelelahan, sementara yang lain menawarkan kiat-kiat untuk menghadapi tempat kerja yang memicu kelelahan atau memulai bisnis sebagai solusi potensial. Beberapa pembaca juga mendiskusikan keampuhan memiliki pelatih gaya hidup atau terapis untuk memerangi kelelahan karyawan, dengan pendapat yang beragam. Pada akhirnya, kesimpulan utamanya adalah bahwa kepedulian terhadap pekerjaan itu penting, namun tidak harus mengorbankan kesejahteraan seseorang."]}),"\n",(0,t.jsx)(n.h2,{id:"pengembangan-perangkat-lunak-dengan-kode-rendah-adalah-bohong",children:"Pengembangan Perangkat Lunak dengan Kode Rendah Adalah Bohong"}),"\n",(0,t.jsxs)(n.p,{children:["(Asli) (",(0,t.jsx)(n.a,{href:"https://jaylittle.com/post/view/2023/4/low-code-software-development-is-a-lie",children:"https://jaylittle.com/post/view/2023/4/low-code-software-development-is-a-lie"}),').\nSeorang pengembang perangkat lunak yang berpengalaman berpendapat bahwa membuat perangkat lunak itu sulit karena klien dan pengembang tidak memahami akar masalah yang ingin mereka selesaikan, bukan karena kesalahan bahasa pengkodean dan alat bantu. Penulis mengkritik gagasan alat "kode rendah" seperti OutSystems, yang menyatakan bahwa alat tersebut tidak menghilangkan kompleksitas yang melekat dan dapat menyebabkan sistem perangkat lunak yang tidak dipikirkan dengan baik, serta mahal dan melibatkan penguncian vendor. Merancang solusi dengan benar adalah bagian tersulit dalam proses pengembangan perangkat lunak, dan tidak ada alat bantu yang dapat menggantikan pemikiran, diskusi, dan perencanaan yang diperlukan.']}),"\n",(0,t.jsxs)(n.p,{children:["(Discussion Service) (",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35578240",children:"http://news.ycombinator.com/item?id=35578240"}),").\nPengembangan perangkat lunak dengan kode rendah berguna untuk masalah yang lebih sederhana tetapi tidak cocok untuk masalah yang kompleks, dan tidak boleh menggantikan pengembang sama sekali. Komentar Discussion Service membahas keterbatasan dan trade-off dari platform low-code, termasuk kemampuan pengujian yang buruk, versi, dan alat debugging yang dapat menyebabkan penguncian vendor. Beberapa ahli menyarankan bahwa alat bantu low-code dapat bermanfaat untuk pembuatan prototipe dan aplikasi tertentu, tetapi yang lain memperingatkan agar tidak terlalu mengandalkannya dan menyarankan untuk memilih alat bantu yang sesuai dengan hati-hati. Meskipun low-code memiliki berbagai kasus penggunaan, definisinya tidak jelas dan berpotensi menyesatkan, dengan Excel dan grafik shader sebagai contohnya."]}),"\n",(0,t.jsx)(n.h2,{id:"kerentanan-eksekusi-kode-jarak-jauh-di-google-yang-tidak-mau-mereka-perbaiki",children:"Kerentanan eksekusi kode jarak jauh di Google yang tidak mau mereka perbaiki"}),"\n",(0,t.jsxs)(n.p,{children:["(Asli) (",(0,t.jsx)(n.a,{href:"https://giraffesecurity.dev/posts/google-remote-code-execution/",children:"https://giraffesecurity.dev/posts/google-remote-code-execution/"}),").\nSeorang peneliti keamanan menemukan kerentanan di Google yang memungkinkan mereka untuk menjalankan kode sewenang-wenang di komputer lebih dari 50 karyawan Google, yang disebabkan oleh kebingungan ketergantungan dalam sistem manajemen Python. Google awalnya mengklasifikasikannya sebagai parah tetapi kemudian mengubahnya menjadi perilaku yang diinginkan. Peneliti khawatir kerentanan tersebut dapat dieksploitasi, karena mereka telah menerima unduhan dari karyawan Google setiap hari, dan menduga Google tidak memahami masalahnya, atau mereka tidak peduli untuk memperbaikinya."]}),"\n",(0,t.jsxs)(n.p,{children:["(Discussion Service) (",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35581532",children:"http://news.ycombinator.com/item?id=35581532"}),").\nKerentanan Remote Code Execution (RCE) yang ditemukan di perangkat lunak Google dilaporkan belum diperbaiki, dengan beberapa pengguna menunjukkan bahwa sistem manajemen paket Java memiliki cara yang lebih aman untuk meng-upload paket daripada sistem Rust, sementara yang lain menyarankan agar ",(0,t.jsx)(n.code,{children:"pip install -extra-index-url"})," mengabaikan registri khusus pengguna, sehingga membuat registri pribadi menjadi tidak berguna. Google memiliki langkah-langkah keamanan tanpa kepercayaan untuk memerangi ancaman orang dalam, tetapi APT dapat menggunakan kerentanan ini untuk mendapatkan pijakan di lingkungan. Kebutuhan akan solusi manajemen paket yang lebih baik dan peran zero-trust dalam mencegah serangan semacam itu juga disoroti."]}),"\n",(0,t.jsx)(n.h2,{id:"pengembangan-hypervisor-dalam-karat",children:"Pengembangan Hypervisor dalam Karat"}),"\n",(0,t.jsxs)(n.p,{children:["(Asli) (",(0,t.jsx)(n.a,{href:"https://memn0ps.github.io/hypervisor-development-in-rust-part-1/",children:"https://memn0ps.github.io/hypervisor-development-in-rust-part-1/"}),").\nArtikel ini menjelaskan pengembangan hypervisor penelitian berbasis Rust untuk virtualisasi Intel VT-x, memberikan contoh kode Rust untuk operasi VMX dan mendiskusikan proses inisialisasi wilayah memori untuk CPU virtual. Artikel ini bertujuan untuk menjadi sumber daya yang berguna bagi para ahli di bidang virtualisasi yang menggunakan Rust. Artikel ini menjaga netralitas dan menyediakan referensi dan kredit."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35579876",children:"Discussion Service"}),".\nSeorang pengguna Hacker News mengomentari artikel tentang virtualisasi CPU dan menyatakan minatnya pada virtualisasi perangkat, menyoroti tantangan yang dihadapi dan mengusulkan solusi baru. Pengguna lain memberikan sumber daya dan alternatif bagi pengguna Linux yang tertarik pada bidang ini."]})]})}function g(a={}){const{wrapper:n}={...(0,r.R)(),...a.components};return n?(0,t.jsx)(n,{...a,children:(0,t.jsx)(k,{...a})}):k(a)}}}]);